  "thing/cloudflare-worker-webapp@1/template.yaml": "id: template.thing.cloudflare-worker-webapp\nkind: thing\nversion: \"1\"\nname: Cloudflare Worker web app\ndescription: A full-stack web app served by one Cloudflare Worker with static assets, D1 storage and cron scheduling.\nsections:\n  - section.ui\n  - section.domain\n  - section.authorization\n  - section.runtime\nnodes:\n  - id: section.ui\n    kind: section\n    name: UI\n    parent: \"$thing\"\n    owningThing: \"$thing\"\n    description: Screens, shared components and affordances.\n  - id: section.domain\n    kind: section\n    name: Domain\n    parent: \"$thing\"\n    owningThing: \"$thing\"\n    description: Entities, operations and invariants.\n  - id: section.authorization\n    kind: section\n    name: Authorization\n    parent: \"$thing\"\n    owningThing: \"$thing\"\n    description: Policies governing who may read or change what.\n  - id: section.runtime\n    kind: section\n    name: Runtime\n    parent: \"$thing\"\n    owningThing: \"$thing\"\n    description: Bindings and deployment surface.\n\n  - id: binding.worker\n    kind: binding\n    name: Worker with static assets\n    parent: section.runtime\n    owningThing: \"$thing\"\n    description: Cloudflare Worker serving the API and the built UI through Workers Static Assets.\n  - id: binding.d1\n    kind: binding\n    name: D1 database\n    parent: section.runtime\n    owningThing: \"$thing\"\n    description: Placeholder relational store. Instances rename or replace it via override (for example binding.contactsStore).\n    provisional: true\n  - id: binding.scheduler\n    kind: binding\n    name: Cron scheduler\n    parent: section.runtime\n    owningThing: \"$thing\"\n    description: Cron Triggers for periodic work.\n\n  - id: component.AppShell\n    kind: component\n    name: AppShell\n    parent: section.ui\n    owningThing: \"$thing\"\n    description: Frame holding the top bar, primary navigation and route outlet.\n  - id: component.TopBar\n    kind: component\n    name: TopBar\n    parent: component.AppShell\n    owningThing: \"$thing\"\n  - id: component.PrimaryNav\n    kind: component\n    name: PrimaryNav\n    parent: component.AppShell\n    owningThing: \"$thing\"\n  - id: component.RouteOutlet\n    kind: component\n    name: RouteOutlet\n    parent: component.AppShell\n    owningThing: \"$thing\"\n  - id: component.StatePanel\n    kind: component\n    name: StatePanel\n    parent: section.ui\n    owningThing: \"$thing\"\n    description: Shared loading, empty and unavailable states.\n    states: [loading, empty, unavailable]\n  - id: component.ErrorSummary\n    kind: component\n    name: ErrorSummary\n    parent: section.ui\n    owningThing: \"$thing\"\n    description: Shared summary of form and request errors.\n\n  - id: policy.authentication\n    kind: policy\n    name: Authentication\n    parent: section.authorization\n    owningThing: \"$thing\"\n    description: Who counts as a signed-in user. Provisional until an auth kit is pinned.\n    provisional: true\n",
